const first = Temporal.ZonedDateTime.from("2024-10-27T02:30[Europe/Berlin]");
const second = Temporal.ZonedDateTime.from("2024-10-27T02:30[Europe/Berlin]", { disambiguation: "later" });
const utc = second.withTimeZone("UTC");

console.log(first.offset);
console.log(second.offset);
console.log(first.until(second).toString());
console.log(first.hoursInDay);
console.log(utc.toString());
console.log(second.equals(utc), Temporal.ZonedDateTime.compare(second, utc));
